public DefaultDetector(MimeTypes types, ServiceLoader loader, Collection<Class<? extends Detector>> excludeDetectors) {
    super(types.getMediaTypeRegistry(), getDefaultDetectors(loader, excludeDetectors));
    this.loader = loader;
    this.mimeTypes = types;
    this.textDetector = new TextDetector();
    this.excludedClasses = excludeDetectors != null ? Collections.unmodifiableCollection(new ArrayList<>(excludeDetectors)) : Collections.emptySet();
}
